package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionDecimalRecallTest {
 private static Question question(String n,String d){return new Question(FractionDecimalRecall.ID,FractionDecimalRecall.prompt(n,d),"poison","999");}
 @Test public void finiteAndRecurringRepresentationsAreExactIncludingNonminimalCyclesAndNines(){
  String[][] values={{"0.(3)","1/3"},{"0.3(3)","1/3"},{"0.(33)","1/3"},{"0.(6)","2/3"},{"0.(9)","1"},{"0.4(9)","1/2"},{"0.12(9)","13/100"},{"1.(9)","2"},{"-2.1(6)","-13/6"},{"−0.50","-1/2"},{"+0.1250","1/8"},{"0.03(3)","1/30"},{"1.2(34)","611/495"},{"0.0(0)","0"}};
  for(String[] c:values)assertEquals(c[0],Expression.number(c[1]),FractionDecimalRecall.exactInput(c[0]));Checker checker=new Checker();Question third=question("1","3");for(String raw:List.of("0.(3)","0.3(3)","0.(33)"))assertTrue(checker.check(third,List.of(),List.of(raw)).correct());for(String raw:List.of("0.333","0.334","0.333333333333"))assertEquals(Checker.Status.WRONG_ANSWER,checker.check(third,List.of(),List.of(raw)).status);assertTrue(checker.check(question("1","1"),List.of(),List.of("0.(9)")).correct());assertTrue(checker.check(question("1","2"),List.of(),List.of("0.4(9)")).correct());
 }
 @Test public void publicOriginalsAndGeneralZeroImproperAndOutsideSelectedDenominatorsRemainValid(){
  Question raw=question("006","012");var g=FractionDecimalRecall.read(raw);assertNotNull(g);assertEquals("006",g.rawNumerator());assertEquals("012",g.rawDenominator());assertEquals(Rational.of(1,2),g.value());assertTrue(g.finitePossible());assertTrue(new Checker().check(raw,List.of(),List.of("0.50")).correct());
  for(String[] c:List.of(new String[]{"0","7","0.0"},new String[]{"4","3","1.(3)"},new String[]{"1","7","0.(142857)"},new String[]{"1","7","0.1(428571)"},new String[]{"9","6","1.5"})){Question q=question(c[0],c[1]);assertNotNull(FractionDecimalRecall.read(q));assertTrue(new Checker().check(q,List.of(),List.of(c[2])).correct());assertEquals(4,HelpPlan.forQuestion(q).size());}
  Question large=question("99999999999999999999","3");assertNotNull(FractionDecimalRecall.read(large));assertTrue(new Checker().check(large,List.of(),List.of("33333333333333333333.0")).correct());Question finite=question("1","73786976294838206464");var f=FractionDecimalRecall.read(finite);assertTrue(f.finitePossible());String exact=f.value().decimalText();assertTrue(HelpPlan.forQuestion(finite).step(3).accepts(exact));assertTrue(new Checker().check(finite,List.of(),List.of(exact)).correct());
 }
 @Test public void fourBlankPublicFramesAndRationalTargetIgnorePrivateMetadataAndPreserveDraft(){
  Question q=question("1","3");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());assertTrue(h.step(0).accepts("1"));assertTrue(h.step(1).accepts("3"));assertTrue(h.step(2).accepts("repeat"));assertFalse(h.step(2).accepts("finite"));assertTrue(h.step(3).accepts("0.(3)"));assertFalse(h.step(3).accepts("0.333"));assertFalse(h.step(3).accepts("1/3"));for(int i=0;i<4;i++){assertEquals("",h.step(i).after);assertFalse(h.step(i).accepts(""));}StudyGuide publicGuide=FractionDecimalRecall.guide(q);assertEquals("1/3",publicGuide.frames.get(3).expected);assertEquals("exactDecimalRecall",publicGuide.frames.get(3).inputFormat);
  HelpPlan.Draft d=h.restore(null,q.id);assertEquals(FractionDecimalRecall.VERSION,d.teachingVersion);d.stage=4;d.entries=new ArrayList<>(List.of("1","3","repeat","0.3(3)"));HelpPlan.Draft restored=h.restore(d.copy(),q.id);assertEquals(4,restored.stage);assertEquals("0.3(3)",h.enteredAnswer(restored));assertSame(stored,q.studyGuide);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);q.expression=null;q.answers=null;assertTrue(new Checker().check(q,List.of("999=999"),List.of("0.(3)"),List.of(Checker.StepKind.FULL)).correct());assertEquals(4,HelpPlan.forQuestion(q).size());
  Question hugePeriod=question("1","99999999999999999989");assertEquals(4,HelpPlan.forQuestion(hugePeriod).size());assertEquals("1/99999999999999999989",FractionDecimalRecall.guide(hugePeriod).frames.get(3).expected);assertTrue(HelpPlan.forQuestion(question("1","1")).step(2).accepts("finite"));assertTrue(HelpPlan.forQuestion(question("1","1")).step(3).accepts("0.(9)"));
 }
 @Test public void referencesOnlyShowCheckedLearnerOriginalsWithoutDecimalPrefill(){
  Question q=question("001","3");assertEquals(Map.of(),FractionDecimalRecall.references(q,2,List.of()));assertEquals(Map.of("분자 n = ","001"),FractionDecimalRecall.references(q,2,List.of("001","999")));assertEquals(Map.of("분자 n = ","001","분모 d = ","3"),FractionDecimalRecall.references(q,3,List.of("001","3","repeat")));assertFalse(FractionDecimalRecall.references(q,3,List.of("001","3","repeat")).containsValue("0.(3)"));assertEquals(Map.of(),FractionDecimalRecall.references(q,4,List.of("001","3","repeat","0.(3)")));
 }
 @Test public void exactInputAndPublicGrammarGuardsDoNotWidenOtherSkills(){
  for(String input:List.of("0."+"0".repeat(119),BigInteger.ONE.shiftLeft(512)+".0","1/3","1e-3","0,333","0.333…","0.(3)+0","((0.(3)))","0. (3)",".(3)","0.()","0.(a)","0.(3","1","1."))assertNull(input,FractionDecimalRecall.exactInput(input));assertEquals(Rational.ZERO,FractionDecimalRecall.exactInput("0."+"0".repeat(118)));
  for(Question q:List.of(question("1","0"),question("-1","3"),question("1".repeat(21),"3"),question("1","1".repeat(21)),question("1e2","3"))){q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(FractionDecimalRecall.read(q));assertNull(HelpPlan.forQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0.0")).status);}assertNull(FractionDecimalRecall.read(null));assertNull(FractionDecimalRecall.guide(null));Question trailing=question("1","3");trailing.prompt+=" trailing";assertNull(FractionDecimalRecall.read(trailing));
  try{Expression.number("0."+"1".repeat(13));fail("Shared decimal guard widened");}catch(IllegalArgumentException expected){}assertNull(FractionDecimalDivision.decimalInput("0.(3)"));
 }
}
